        "resourceType": "Observation",
        "id": "observation-20",
        "status": "final",
        "code": {
          "text": "Oral intake and appetite"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Tolerating fluids; decreased appetite but eating small meals."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-21",
