        "resourceType": "Observation",
        "id": "observation-21",
        "status": "final",
        "code": {
          "text": "Pregnancy status"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient states she is not pregnant."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-22",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-22",
        "status": "final",
        "code": {
          "text": "Varicella exposure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Works in childcare; several children recently had varicella, including a child sent home with chickenpox the previous week."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-23",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-23",
        "status": "final",
        "code": {
          "text": "Chickenpox and vaccination history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Previous chickenpox history is uncertain. Vaccination status is uncertain; patient reports her mother thinks she had all her vaccinations."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-24",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-24",
        "status": "final",
        "code": {
          "text": "Assessment of systemic illness"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Systemically mild at assessment. No features suggesting pneumonitis, encephalitis or hepatitis."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Paracetamol"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "500 mg, 1–2 tablets as needed for headache",
            "asNeededBoolean": true,
            "doseAndRate": [
              {
                "doseRange": {
                  "low": {
                    "value": 1,
                    "unit": "tablet"
                  },
                  "high": {
                    "value": 2,
                    "unit": "tablets"
                  }
                }
              }
            ]
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Valaciclovir"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "1 g orally three times daily for 7 days",
            "route": {
              "text": "oral"
            },
            "timing": {
              "repeat": {
                "frequency": 3,
                "period": 1,
                "periodUnit": "d",
                "boundsDuration": {
                  "value": 7,
                  "unit": "days"
                }
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 1,
                  "unit": "g"
                }
              }
            ]
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-2",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-2",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Paracetamol"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "1 g four times daily as needed; maximum 4 g per 24 hours",
            "asNeededBoolean": true,
            "timing": {
              "repeat": {
                "frequency": 4,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 1,
                  "unit": "g"
                }
              }
            ],
            "maxDosePerPeriod": {
              "numerator": {
                "value": 4,
                "unit": "g"
              },
              "denominator": {
                "value": 24,
                "unit": "hours"
              }
            }
          }
        ]
      }
    }
  ]
}

